import{_ as t,o as i,c as r,a4 as a}from"./chunks/framework.DMdI2MFY.js";const h=JSON.parse('{"title":"Certificates","description":"This page list compliance certificates for HUNT Cloud.","frontmatter":{"title":"Certificates","category":"HUNT Cloud","permalink":"/govern-science/compliance/certificates","outline":1,"description":"This page list compliance certificates for HUNT Cloud."},"headers":[],"relativePath":"govern-science/compliance/certificates.md","filePath":"govern-science/compliance/certificates.md"}'),s={name:"govern-science/compliance/certificates.md"};function c(o,e,l,n,f,d){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="certificates" tabindex="-1">Certificates <a class="header-anchor" href="#certificates" aria-label="Permalink to &quot;Certificates&quot;">​</a></h1><p><strong>HUNT Cloud complies with three international management systems: quality management (ISO 9001); information security (ISO/IEC 27001); and information privacy (ISO/IEC 27701).</strong></p><p>For each certificate, independent auditors examines our governance, management, infrastructure, services and operations. Reports from these audits are available to data controllers on request.</p><p>Our ISO 9001 and ISO/IEC 27001 certificates have been issued since 2017, while the ISO/IEC 27701 certificate has been issued since 2024.</p><nav class="table-of-contents"><ul><li><a href="#iso-iec-9001-certificate">ISO/IEC 9001 certificate</a></li><li><a href="#iso-iec-27001-certificate">ISO/IEC 27001 certificate</a></li><li><a href="#iso-iec-27701-certificate">ISO/IEC 27701 certificate</a></li></ul></nav><h2 id="iso-iec-9001-certificate" tabindex="-1">ISO/IEC 9001 certificate <a class="header-anchor" href="#iso-iec-9001-certificate" aria-label="Permalink to &quot;ISO/IEC 9001 certificate&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Current version</p><p><a href="https://assets.hdc.ntnu.no/assets/certificates/hunt-cloud-certificate-iso9001-2025.pdf" target="_blank" rel="noreferrer">NS-EN ISO 9001:2015 Certificate</a> (PDF)</p></div><p>Our compliance with the international standard in quality management «ISO 9001» is certified by DNV, Norway. The certificate was issues as part of HUNT Research Centre&#39;s main certificate from 2017 to 2025, and as a stand-along certificate for HUNT Cloud from 2025.</p><details class="details custom-block"><summary>List of issued certificates</summary><p><strong>Period #4: 2025-2028</strong></p><ul><li><a href="https://assets.hdc.ntnu.no/assets/certificates/hunt-cloud-certificate-iso9001-2025.pdf" target="_blank" rel="noreferrer">Download certificate</a> (PDF)</li><li>ISO version: NS-EN ISO 9001:2015</li><li>Issued by: <a href="https://www.dnv.com/" target="_blank" rel="noreferrer">DNV</a>, Norway</li><li>Certificate ID: C692937</li><li>Issued: 2025-03-13</li></ul><p><strong>Period #3: 2023-2025</strong></p><ul><li><a href="https://assets.hdc.ntnu.no/assets/certificates/hunt-cloud-certificate-iso9001-2023.pdf" target="_blank" rel="noreferrer">Download certificate</a> (PDF)</li><li>ISO version: NS-EN ISO 9001:2015</li><li>Issued by: <a href="https://www.kiwa.com/en/" target="_blank" rel="noreferrer">Kiwa</a>, Norway</li><li>Certificate ID: 3-911</li><li>Issued: 2023-03-21</li></ul><p><strong>Period #2: 2020-2023</strong></p><ul><li><a href="https://assets.hdc.ntnu.no/assets/certificates/hunt-cloud-certificate-iso9001-2020.pdf" target="_blank" rel="noreferrer">Download certificate</a> (PDF)</li><li>ISO version: NS-EN ISO 9001:2015</li><li>Issued by: <a href="https://www.kiwa.com/en/" target="_blank" rel="noreferrer">Kiwa</a>, Norway</li><li>Certificate ID: 3-911</li><li>Issued: 2022-03-18</li></ul><p><strong>Period #1: 2017-2020</strong></p><ul><li><a href="https://assets.hdc.ntnu.no/assets/certificates/hunt-cloud-certificate-iso9001-2017.pdf" target="_blank" rel="noreferrer">Download certificate</a> (PDF)</li><li>ISO version: NS-EN ISO 9001:2015</li><li>Issued by: <a href="https://www.kiwa.com/en/" target="_blank" rel="noreferrer">Kiwa</a>, Norway</li><li>Certificate ID: 3-911</li><li>Issued: 2017-08-15</li></ul></details><h2 id="iso-iec-27001-certificate" tabindex="-1">ISO/IEC 27001 certificate <a class="header-anchor" href="#iso-iec-27001-certificate" aria-label="Permalink to &quot;ISO/IEC 27001 certificate&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Current version</p><p><a href="https://assets.hdc.ntnu.no/assets/certificates/hunt-cloud-certificate-iso27001-2026.pdf" target="_blank" rel="noreferrer">NS-EN ISO 27001:2022 Certificate</a> (PDF)</p></div><p>Our compliance with the international standard in information security management «<a href="https://www.iso.org/isoiec-27001-information-security.html" target="_blank" rel="noreferrer">ISO/IEC 27001</a>» is certified in accordance with our Statement of Applicability (SoA) by DNV, Norway. The certificate includes controls from ISO/IEC 27017, security for cloud services, and ISO/IEC 27018, privacy for cloud services.</p><details class="details custom-block"><summary>List of issued certificates</summary><p><strong>Period #3: 2024-2027</strong></p><ul><li><a href="https://assets.hdc.ntnu.no/assets/certificates/hunt-cloud-certificate-iso27001-2026.pdf" target="_blank" rel="noreferrer">Download certificate</a> (PDF)</li><li>ISO version: NS-EN ISO 27001:2022</li><li>Issued by: <a href="https://www.dnv.com/" target="_blank" rel="noreferrer">DNV</a>, Norway</li><li>Certificate ID: C624087</li><li>Issued: 2024-02-14</li></ul><p><strong>Period #2: 2021-2024</strong></p><ul><li><a href="https://assets.hdc.ntnu.no/assets/certificates/hunt-cloud-certificate-iso27001-2021.pdf" target="_blank" rel="noreferrer">Download certificate</a> (PDF)</li><li>ISO version: NS-EN ISO 27001:2017</li><li>Issued by: <a href="https://www.kiwa.com/en/" target="_blank" rel="noreferrer">Kiwa</a>, Norway</li><li>Certificate ID: 2189</li><li>Issued: 2021-02-22</li></ul><p><strong>Period #1: 2017-2020</strong></p><ul><li><a href="https://assets.hdc.ntnu.no/assets/certificates/hunt-cloud-certificate-iso27001-2017.pdf" target="_blank" rel="noreferrer">Download certificate</a> (PDF)</li><li>ISO version: NS-ISO/IEC 27001:2013</li><li>Issued by: <a href="https://www.nemko.com/" target="_blank" rel="noreferrer">Nemko</a>, Norway</li><li>Certificate ID: 904033</li><li>Issued: 2017-12-20</li></ul></details><h2 id="iso-iec-27701-certificate" tabindex="-1">ISO/IEC 27701 certificate <a class="header-anchor" href="#iso-iec-27701-certificate" aria-label="Permalink to &quot;ISO/IEC 27701 certificate&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Current version</p><p><a href="https://assets.hdc.ntnu.no/assets/certificates/hunt-cloud-certificate-iso27701-2026.pdf" target="_blank" rel="noreferrer">NS-EN ISO 27701:2019 Certificate</a> (PDF)</p></div><p>Our compliance with the international standard for privacy information management «<a href="https://www.iso.org/standard/27701" target="_blank" rel="noreferrer">ISO/IEC 27701</a>» is certified in accordance with our Statement of Applicability (SoA) by DNV, Norway.</p><details class="details custom-block"><summary>List of issued certificates</summary><p><strong>Period #1: 2024-2027</strong></p><ul><li><a href="https://assets.hdc.ntnu.no/assets/certificates/hunt-cloud-certificate-iso27701-2026.pdf" target="_blank" rel="noreferrer">Download certificate</a> (PDF)</li><li>ISO version: NS-EN ISO 27701:2022</li><li>Issued by: <a href="https://www.dnv.com/" target="_blank" rel="noreferrer">DNV</a>, Norway</li><li>Certificate ID: C848099</li><li>Issued: 2024-02-14</li></ul></details>',17)])])}const p=t(s,[["render",c]]);export{h as __pageData,p as default};
